import {
  METHODS,
  mistakeCounts,
  parsePredictionCsv,
  joinPredictions,
  summarize,
  selectCategory,
  filterExamples,
  paginate,
  displayCategory,
} from '../app/model.js';

// These are invented examples from PLAN.md, separate from the public default data.
// Expected values below are literal hand calculations, never generated by the model.
const fixture = [
  ['a1', 'A', 'A', 'A', 'A', 'First A example'],
  ['a2', 'A', 'A', 'A', 'A', 'Second A example'],
  ['a3', 'A', 'A', 'A', 'B', 'Third A example'],
  ['a4', 'A', 'B', 'A', 'B', 'Fourth A example'],
  ['b1', 'B', 'B', 'B', 'B', 'First B example'],
  ['b2', 'B', 'A', 'B', 'B', 'Second B example'],
  ['b3', 'B', 'A', 'A', 'B', 'Third B example'],
  ['b4', 'B', 'A', 'A', 'A', 'Fourth B example'],
];
const requiredHeaders = ['case_id', 'text', 'true_label', 'predicted_label'];
const filenames = [
  'bow_logistic_regression_test_predictions_3080.csv',
  'fine_tuned_classifier_test_predictions_3080.csv',
  'llm_prompting_test_predictions_3080.csv',
];

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function equal(actual, expected, label = 'value') {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${label}: expected ${JSON.stringify(expected)}, observed ${JSON.stringify(actual)}`);
  }
}

function near(actual, expected, label = 'value') {
  assert(typeof actual === 'number' && Math.abs(actual - expected) < 1e-9,
    `${label}: expected ${expected}, observed ${actual}`);
}

function rejects(fn, label) {
  let error;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof Error && error.message.trim().length > 0,
    `${label}: expected a readable Error; invalid data must not produce a comparison.`);
}

function csvCell(value) {
  const text = String(value);
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

function csv(rows, headers = requiredHeaders, newline = '\n') {
  return [headers, ...rows.map(row => headers.map(header => row[header] ?? ''))]
    .map(row => row.map(csvCell).join(','))
    .join(newline);
}

function fixtureRows(methodIndex) {
  return fixture.map(([id, reference, bow, fine, llm, text]) => ({
    case_id: id,
    text,
    true_label: reference,
    predicted_label: [bow, fine, llm][methodIndex],
  }));
}

function datasetsFromRows(rowsByMethod) {
  return rowsByMethod.map((rows, index) => ({
    method: METHODS[index],
    ...parsePredictionCsv(csv(rows), METHODS[index].name),
  }));
}

function fixtureData() {
  return joinPredictions(datasetsFromRows(METHODS.map((_, index) => fixtureRows(index))));
}

function counts(cases, expectedCorrect, expectedIncorrect, expectedTotal) {
  const metrics = summarize(cases);
  equal(metrics.map(metric => metric.id), ['bow', 'fine', 'llm'], 'method order');
  equal(metrics.map(metric => metric.correct), expectedCorrect, 'correct counts');
  equal(metrics.map(metric => metric.incorrect), expectedIncorrect, 'incorrect counts');
  equal(cases.length, expectedTotal[0], 'independently expected example count');
  equal(metrics.map(metric => metric.total), expectedTotal, 'common denominator');
  metrics.forEach((metric, index) => {
    if (cases.length === 0) equal(metric.accuracy, null, 'empty accuracy');
    else near(metric.accuracy, expectedCorrect[index] / cases.length * 100, `${metric.id} unrounded accuracy`);
    equal(metric.correct + metric.incorrect, metric.total, `${metric.id} reconciled count`);
  });
  return metrics;
}

// The optional fetcher lets the same checks run under Node without a test framework.
// Browser URLs are relative to this module, because the test server serves project root.
export async function runTests({ fetcher = globalThis.fetch, onResult = () => {} } = {}) {
  const results = [];
  async function check(name, fn) {
    let result;
    try {
      await fn();
      result = { name, passed: true };
    } catch (error) {
      result = { name, passed: false, error: error.stack || error.message || String(error) };
    }
    results.push(result);
    onResult(result);
  }

  await check('The eight-example fixture reproduces independently calculated totals', () => {
    const { cases, categories } = fixtureData();
    equal(cases.length, 8, 'fixture size');
    equal(categories, ['A', 'B'], 'fixture categories');
    const metrics = counts(cases, [4, 6, 5], [4, 2, 3], [8, 8, 8]);
    equal(metrics.map(metric => metric.accuracy.toFixed(2)), ['50.00', '75.00', '62.50'], 'display precision');
  });

  await check('Mistake groups partition errors without dropping shared wrong answers', () => {
    const { cases } = fixtureData();
    equal(mistakeCounts(cases), [3, 2, 2, 1], 'independent fixture partition');
    equal(filterExamples(cases, {view: 'wrong1'}).map(row => row.id), ['a3', 'b2'], 'one method wrong');
    equal(filterExamples(cases, {view: 'wrong2'}).map(row => row.id), ['a4', 'b3'], 'two methods wrong');
    equal(filterExamples(cases, {view: 'wrong3'}).map(row => row.id), ['b4'], 'shared wrong answer included');
    equal(filterExamples(cases, {view: 'wrong2', search: 'Fourth'}).map(row => row.id), ['a4'], 'group and search intersect');
    equal(mistakeCounts([]), [0, 0, 0, 0], 'empty groups');
    equal(mistakeCounts(selectCategory(cases, 'A')), [2, 1, 1, 0], 'category partition');
  });

  await check('Category filtering changes the fixture’s denominator and leading method', () => {
    const { cases } = fixtureData();
    counts(selectCategory(cases, 'A'), [3, 4, 2], [1, 0, 2], [4, 4, 4]);
    counts(selectCategory(cases, 'B'), [1, 2, 3], [3, 2, 1], [4, 4, 4]);
    equal(selectCategory(cases).length, 8, 'default all-category scope');
  });

  await check('Incorrectness and disagreement have different independently known counts', () => {
    const { cases } = fixtureData();
    equal(filterExamples(cases, { view: 'incorrect' }).map(item => item.id), ['a3', 'a4', 'b2', 'b3', 'b4'], 'any incorrect IDs');
    equal(filterExamples(cases, { view: 'disagree' }).map(item => item.id), ['a3', 'a4', 'b2', 'b3'], 'disagreement IDs');
    const agreedMistake = cases.find(item => item.id === 'b4');
    equal(agreedMistake.anyIncorrect, true, 'agreed wrong answer is still incorrect');
    equal(agreedMistake.disagree, false, 'agreed wrong answer is not disagreement');
    equal(cases.filter(item => Object.values(item.correct).every(value => !value)).length, 1, 'all-three-wrong count');
  });

  await check('Search filters only example text, ignores case, and leaves headline data untouched', () => {
    const { cases } = fixtureData();
    const before = summarize(cases);
    equal(filterExamples(cases, { view: 'all', search: 'THIRD' }).map(item => item.id), ['a3', 'b3'], 'case-insensitive text search');
    equal(filterExamples(cases, { view: 'incorrect', search: 'First' }).length, 0, 'search and view intersection');
    equal(filterExamples(cases, { view: 'all', search: 'a1' }).length, 0, 'case ID is not example text');
    equal(filterExamples(cases, { view: 'all', search: 'no such phrase' }).length, 0, 'no search matches');
    equal(summarize(cases), before, 'search does not mutate accuracy scope');
  });

  await check('Category and example filters combine while preserving the category metric scope', () => {
    const { cases } = fixtureData();
    const categoryCases = selectCategory(cases, 'A');
    equal(filterExamples(categoryCases, { view: 'incorrect' }).map(item => item.id), ['a3', 'a4'], 'category mistake intersection');
    equal(filterExamples(categoryCases, { view: 'disagree', search: 'Fourth' }).map(item => item.id), ['a4'], 'category/view/search intersection');
    counts(categoryCases, [3, 4, 2], [1, 0, 2], [4, 4, 4]);
  });

  await check('CSV parsing preserves BOM, CRLF, quoted commas, quotes, line breaks, and string IDs', () => {
    const text = 'A comma, an escaped "quote", and\na second line.';
    const source = '\uFEFF' + csv([{
      case_id: '0007', text, true_label: 'A', predicted_label: 'A',
    }], requiredHeaders, '\r\n') + '\r\n\r\n';
    const parsed = parsePredictionCsv(source, 'CSV fixture');
    equal(parsed.rows.length, 1, 'blank trailing lines ignored');
    equal(parsed.rows[0].case_id, '0007', 'leading-zero ID');
    equal(parsed.rows[0].text, text, 'quoted text unchanged');
    equal(parsed.rows[0].true_label, 'A', 'reference string');
  });

  await check('An entirely blank line between valid CSV records is ignored', () => {
    const source = csv(fixtureRows(0).slice(0, 2)).replace('\na2,', '\n\na2,');
    equal(parsePredictionCsv(source, 'Blank-line fixture').rows.length, 2, 'valid record count');
  });

  await check('Malformed CSV quotes and inconsistent column counts stop parsing', () => {
    rejects(() => parsePredictionCsv('case_id,text,true_label,predicted_label\n1,"not closed,A,A'), 'unterminated quote');
    rejects(() => parsePredictionCsv('case_id,text,true_label,predicted_label\n1,hello,A,A,extra'), 'extra column');
    rejects(() => parsePredictionCsv('case_id,text,true_label,predicted_label\n1,hello,A'), 'missing column');
  });

  await check('Missing required headers and absent CSV content produce readable errors', () => {
    rejects(() => parsePredictionCsv('case_id,text,true_label\n1,hello,A'), 'missing prediction header');
    rejects(() => parsePredictionCsv('   \n\n'), 'no header');
  });

  await check('Duplicate CSV headers are rejected instead of silently renamed', () => {
    rejects(() => parsePredictionCsv('case_id,text,true_label,predicted_label,text\n1,hello,A,A,other'), 'duplicate column');
  });

  await check('Blank or whitespace-only required fields stop parsing', () => {
    rejects(() => parsePredictionCsv('case_id,text,true_label,predicted_label\n,,,'), 'delimiter-only record');
    for (const header of requiredHeaders) {
      const row = { case_id: '1', text: 'A valid example', true_label: 'A', predicted_label: 'A' };
      row[header] = '';
      rejects(() => parsePredictionCsv(csv([row]), 'Blank-field fixture'), `blank ${header}`);
      row[header] = '   ';
      rejects(() => parsePredictionCsv(csv([row]), 'Blank-field fixture'), `whitespace ${header}`);
    }
  });

  await check('Duplicate IDs block a comparison instead of double-counting examples', () => {
    const rows = METHODS.map((_, index) => fixtureRows(index));
    rows[1].push({ ...rows[1][0] });
    rejects(() => joinPredictions(datasetsFromRows(rows)), 'duplicate ID');
  });

  await check('Examples join by ID when the method files have different row orders', () => {
    const rows = METHODS.map((_, index) => fixtureRows(index));
    rows[1].reverse();
    rows[2] = [...rows[2].slice(3), ...rows[2].slice(0, 3)];
    const { cases } = joinPredictions(datasetsFromRows(rows));
    counts(cases, [4, 6, 5], [4, 2, 3], [8, 8, 8]);
    equal(cases.find(item => item.id === 'a4').predictions, { bow: 'B', fine: 'A', llm: 'B' }, 'ID-matched predictions');
  });

  await check('Missing or substituted IDs block a comparison instead of silently dropping rows', () => {
    const rows = METHODS.map((_, index) => fixtureRows(index));
    rows[1] = rows[1].slice(1);
    rejects(() => joinPredictions(datasetsFromRows(rows)), 'missing ID');
    rows[1] = fixtureRows(1);
    rows[1][0].case_id = 'different-id';
    rejects(() => joinPredictions(datasetsFromRows(rows)), 'same-size different ID set');
  });

  await check('Mismatched reference text or categories block a comparison', () => {
    for (const field of ['text', 'true_label']) {
      const rows = METHODS.map((_, index) => fixtureRows(index));
      rows[2][0][field] = field === 'text' ? 'A changed reference example' : 'B';
      rejects(() => joinPredictions(datasetsFromRows(rows)), `mismatched ${field}`);
    }
  });

  await check('A prediction outside the known reference categories blocks a comparison', () => {
    const rows = METHODS.map((_, index) => fixtureRows(index));
    rows[2][0].predicted_label = 'Unknown';
    rejects(() => joinPredictions(datasetsFromRows(rows)), 'unknown predicted category');
  });

  await check('Non-ok method statuses and nonempty error fields block the data', () => {
    const headers = [...requiredHeaders, 'status', 'error'];
    const row = { ...fixtureRows(2)[0], status: 'failed', error: '' };
    rejects(() => parsePredictionCsv(csv([row], headers), 'Status fixture'), 'non-ok status');
    row.status = 'ok';
    row.error = 'synthetic failure';
    rejects(() => parsePredictionCsv(csv([row], headers), 'Error fixture'), 'error text despite ok status');
    row.error = '';
    equal(parsePredictionCsv(csv([row], headers), 'Valid status fixture').rows.length, 1, 'ok status accepted');
  });

  await check('Contradictory saved correctness flags warn but do not override category equality', () => {
    const datasets = METHODS.map((method, index) => {
      const rows = fixtureRows(index).map(row => ({ ...row, correct: String(row.true_label === row.predicted_label) }));
      if (index === 0) rows[0].correct = 'false';
      return { method, ...parsePredictionCsv(csv(rows, [...requiredHeaders, 'correct']), method.name) };
    });
    assert(datasets[0].warnings.length > 0, 'Contradictory flag did not produce a warning.');
    const joined = joinPredictions(datasets);
    assert(joined.warnings.length > 0, 'The data warning did not reach joined results.');
    counts(joined.cases, [4, 6, 5], [4, 2, 3], [8, 8, 8]);
    equal(joined.cases.find(item => item.id === 'a1').correct.bow, true, 'label equality is authoritative');
  });

  await check('Empty valid files produce no examples and unavailable accuracy', () => {
    const joined = joinPredictions(datasetsFromRows([[], [], []]));
    equal(joined.cases, [], 'empty examples');
    equal(joined.categories, [], 'empty categories');
    counts(joined.cases, [0, 0, 0], [0, 0, 0], [0, 0, 0]);
    equal(filterExamples(joined.cases, { view: 'incorrect' }), [], 'empty filtered list');
  });

  await check('Pagination shows correct ranges, a partial final page, and clamped bounds', () => {
    const cases = Array.from({ length: 53 }, (_, index) => ({ id: String(index + 1) }));
    const first = paginate(cases, 1, 25);
    equal([first.page, first.totalPages, first.total, first.start, first.end], [1, 3, 53, 1, 25], 'first range');
    equal(first.items.map(item => item.id), Array.from({ length: 25 }, (_, index) => String(index + 1)), 'first page IDs');
    const last = paginate(cases, 3, 25);
    equal([last.page, last.start, last.end], [3, 51, 53], 'last range');
    equal(last.items.map(item => item.id), ['51', '52', '53'], 'partial final page');
    equal(paginate(cases, 99, 25).page, 3, 'page beyond final clamps');
    equal(paginate(cases, 0, 25).page, 1, 'page below first clamps');
  });

  await check('Pagination’s empty state has no fictitious examples or invalid range', () => {
    const page = paginate([], 1, 25);
    equal(page.items, [], 'empty page');
    equal([page.page, page.totalPages, page.total, page.start, page.end], [1, 0, 0, 0, 0], 'empty range');
  });

  await check('Imported markup-like text stays literal through parsing, joining, and search', () => {
    const text = '<img src=x onerror="alert(1)"> & <script>fake()</script>';
    const rows = METHODS.map((_, index) => fixtureRows(index));
    rows.forEach(methodRows => { methodRows[0].text = text; });
    const joined = joinPredictions(datasetsFromRows(rows));
    equal(joined.cases.find(item => item.id === 'a1').text, text, 'markup-like text preserved as a string');
    equal(filterExamples(joined.cases, { view: 'all', search: '<script>' }).map(item => item.id), ['a1'], 'literal markup search');
  });

  await check('Display labels replace underscores while raw category values remain intact', () => {
    equal(displayCategory('beneficiary_not_allowed'), 'Beneficiary not allowed', 'readable category');
    const { cases, categories } = fixtureData();
    displayCategory(categories[0]);
    equal(categories, ['A', 'B'], 'display does not mutate categories');
    equal(cases[0].trueLabel, 'A', 'raw reference unchanged');
  });

  let realData;
  await check('The three bundled public CSVs load and align as 3,080 cases in 77 categories', async () => {
    const datasets = await Promise.all(METHODS.map(async (method, index) => {
      const response = await fetcher(new URL(`../app/public/data/${filenames[index]}`, import.meta.url));
      assert(response.ok, `${method.name}: local data request failed (${response.status}).`);
      const parsed = parsePredictionCsv(await response.text(), method.name);
      equal(parsed.rows.length, 3080, `${method.id} input rows`);
      return { method, ...parsed };
    }));
    realData = joinPredictions(datasets);
    equal(realData.cases.length, 3080, 'shared case count');
    equal(realData.categories.length, 77, 'category count');
    equal(realData.warnings.length, 0, 'verified inputs have no contradictory flags');
    equal(realData.categories.map(category => selectCategory(realData.cases, category).length), Array(77).fill(40), 'all category denominators');
  });

  function requireRealData() {
    assert(realData, 'Bundled data was unavailable; this real-data check could not run.');
    return realData.cases;
  }

  await check('The bundled overview matches the plan’s independent counts and rounded accuracies', () => {
    const cases = requireRealData();
    const metrics = counts(cases, [2724, 2841, 2900], [356, 239, 180], [3080, 3080, 3080]);
    equal(metrics.map(metric => metric.accuracy.toFixed(2)), ['88.44', '92.24', '94.16'], 'rounded overview');
  });

  await check('The real mistake/disagreement counts distinguish agreement from correctness', () => {
    const cases = requireRealData();
    equal(filterExamples(cases, { view: 'incorrect' }).length, 539, 'any error');
    equal(mistakeCounts(cases), [2541, 355, 132, 52], 'independent full-data partition');
    equal(['wrong1','wrong2','wrong3'].map(view => filterExamples(cases, {view}).length), [355,132,52], 'real group filtering');
    equal(filterExamples(cases, { view: 'disagree' }).length, 511, 'disagreement');
    equal(cases.filter(item => Object.values(item.correct).every(value => !value)).length, 52, 'all three wrong');
    const defaultPage = paginate(filterExamples(cases, { view: 'incorrect' }));
    equal([defaultPage.start, defaultPage.end, defaultPage.total, defaultPage.totalPages], [1, 25, 539, 22], 'default pagination');
  });

  await check('Beneficiary not allowed exposes the agreed change in the leading method', () => {
    const selected = selectCategory(requireRealData(), 'beneficiary_not_allowed');
    const metrics = counts(selected, [35, 36, 14], [5, 4, 26], [40, 40, 40]);
    equal(metrics.map(metric => metric.accuracy.toFixed(2)), ['87.50', '90.00', '35.00'], 'category accuracy');
    equal(filterExamples(selected, { view: 'incorrect' }).length, 26, 'category any error');
    equal(filterExamples(selected, { view: 'disagree' }).length, 25, 'category disagreement');
  });

  await check('Card arrival preserves the two-method tie and independently known mistakes', () => {
    const selected = selectCategory(requireRealData(), 'card_arrival');
    const metrics = counts(selected, [34, 34, 32], [6, 6, 8], [40, 40, 40]);
    equal(metrics.map(metric => metric.accuracy.toFixed(2)), ['85.00', '85.00', '80.00'], 'category tie');
    equal(filterExamples(selected, { view: 'incorrect' }).length, 11, 'category any error');
    equal(filterExamples(selected, { view: 'disagree' }).length, 8, 'category disagreement');
  });

  return {
    total: results.length,
    passed: results.filter(result => result.passed).length,
    failed: results.filter(result => !result.passed).length,
    results,
  };
}

// Kept separate from runTests so the 28 reusable calculation/data checks also run
// in Node. These two checks require the real browser's DOM and FontFaceSet.
export async function runBrowserChecks({ browserDocument = globalThis.document, onResult = () => {} } = {}) {
  const results = [];
  let fontFaces = [];
  async function check(name, kind, fn) {
    let result;
    try {
      const details = await fn();
      result = { name, kind, passed: true, details };
    } catch (error) {
      result = { name, kind, passed: false, error: error.stack || error.message || String(error) };
    }
    results.push(result);
    onResult(result);
  }

  await check('The three canonical local font faces are actually loaded', 'font', async () => {
    assert(browserDocument?.fonts, 'This browser does not expose the FontFaceSet needed for verification.');
    const required = [
      { family: 'EB Garamond', weight: '400' },
      { family: 'Open Sans', weight: '400' },
      { family: 'Open Sans', weight: '600' },
    ];
    // Explicitly request every face, including the regular and semibold samples
    // visibly rendered by index.html; then wait for real font loading to finish.
    const loaded = await Promise.all(required.map(({ family, weight }) =>
      browserDocument.fonts.load(`${weight} 20px "${family}"`, 'Prediction comparison dashboard')));
    await browserDocument.fonts.ready;
    const cleanFamily = family => family.replace(/^['"]|['"]$/g, '');
    fontFaces = [...browserDocument.fonts].map(face => ({
      family: cleanFamily(face.family),
      weight: face.weight,
      style: face.style,
      status: face.status,
    }));
    required.forEach(({ family, weight }, index) => {
      assert(loaded[index].some(face => cleanFamily(face.family) === family && face.weight === weight && face.status === 'loaded'),
        `${family} ${weight}: fonts.load did not return an actually loaded matching face.`);
      assert(fontFaces.some(face => face.family === family && face.weight === weight && face.style === 'normal' && face.status === 'loaded'),
        `${family} ${weight}: the browser's actual FontFace entries do not include a loaded normal face.`);
    });
    return required.map(({ family, weight }) => `${family} ${weight} loaded`).join('; ');
  });

  await check('The dashboard’s real row renderer treats markup-like text as literal text', 'render', async () => {
    assert(browserDocument, 'A browser document is required for the renderer check.');
    const { createExampleRow } = await import('../app/render.js');
    const text = '<img src=x onerror="alert(1)"> & <script>fake()</script>';
    const row = createExampleRow({
      id: 'synthetic-safe-text',
      text,
      trueLabel: 'A',
      predictions: { bow: 'A', fine: 'B', llm: 'A' },
      correct: { bow: true, fine: false, llm: true },
      anyIncorrect: true,
      disagree: true,
    });
    // Inspect the detached row; source-like text is never inserted as HTML.
    equal(row.tagName, 'TR', 'real renderer returns a table row');
    equal(row.querySelector('.request-text')?.textContent, text, 'literal text in rendered request cell');
    assert(row.textContent.includes(text), 'The full markup-like string did not remain in the row text.');
    equal(row.querySelectorAll('img,script').length, 0, 'no active image or script elements');
    equal(row.querySelectorAll('td').length, 5, 'all example/reference/method cells');
    equal([...row.querySelectorAll('.answer-state')].map(node => node.textContent), ['Correct', 'Incorrect', 'Correct'], 'explicit answer labels');
    return 'Literal text preserved; no image or script nodes were created.';
  });

  return {
    total: results.length,
    passed: results.filter(result => result.passed).length,
    failed: results.filter(result => !result.passed).length,
    results,
    fontFaces,
  };
}
